from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SKIP = {".git", ".venv", "dist", "__pycache__", "data"}
FORBIDDEN = (
    "eazyml",
    "co-authored-by",
    "proposed design",
    "generated by",
    "coding assistant",
)


def test_repository_text_does_not_carry_drafting_notes():
    offenders = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        if any(part in SKIP for part in path.parts):
            continue
        if path.suffix.lower() not in {".py", ".md", ".html", ".tf", ".yml", ".yaml", ".json", ".toml"}:
            continue
        if path.parts[-2:] == ("tests", "test_docs.py"):
            continue
        text = path.read_text(errors="ignore").lower()
        for phrase in FORBIDDEN:
            if phrase in text:
                offenders.append(f"{path.relative_to(ROOT)}: {phrase}")
    assert offenders == []
